jsLibrary.linkedinHome:
// LinkedIn (desktop): mark the Home feed page so its CSS can hide the feed. The post box and both
// sidebars stay, so no hint is drawn over the page.
// A post opened from a notification goes to its own page, so it still opens with the feed hidden.
(function () {
  if (!/linkedin\.com$/.test(location.hostname)) return;
  var FO = window.__feedoff;
  function on() { return !FO || !FO.enabled || FO.enabled.indexOf('homefeed') !== -1; }
  function isHome() { return /^\/(feed\/?|)$/.test(location.pathname) || /^\/feed\/(update|hashtag)?\/?$/.test(location.pathname); }
  // Notifications link to the feed with one post pinned on top (/feed/?highlightedUpdateUrn=...).
  // With the feed hidden that would be a blank page, so open the post on its own page instead.
  var sent = '';
  function urnFrom(pathname, search) {
    if (!/^\/feed\/?$/.test(pathname)) return null;
    var m = /[?&]highlightedUpdateUrns?=([^&#]+)/.exec(search || '');
    if (!m) return null;
    var urn; try { urn = decodeURIComponent(m[1]); } catch (e) { return null; }
    urn = urn.replace(/^[(\[]+/, '').split(',')[0];
    return /^urn:li:(activity|ugcPost|share):[0-9]+$/.test(urn) ? urn : null;
  }
  function openPost() {
    if (!on()) return false;
    var urn = urnFrom(location.pathname, location.search);
    if (!urn) return false;
    if (sent !== urn) { sent = urn; mark(urn); location.replace('/feed/update/' + urn + '/'); }
    return true;
  }
  // LinkedIn's post page puts the Home feed behind itself in history, so Back from a post opened
  // this way would land on the hidden feed. Remember the post and send that Back to Notifications.
  var KEY = '__feedoff_li_post', bouncing = false;
  function mark(urn) { try { sessionStorage.setItem(KEY, urn); } catch (e) {} }
  function marked() { try { return sessionStorage.getItem(KEY); } catch (e) { return null; } }
  function unmark() { try { sessionStorage.removeItem(KEY); } catch (e) {} }
  function backFromPost() {
    var m = marked();
    if (!m) return false;
    var path; try { path = decodeURIComponent(location.pathname); } catch (e) { path = location.pathname; }
    if (path.indexOf('/feed/update/' + m) === 0) return false;
    if (!on() || !isHome()) { unmark(); return false; }
    if (!bouncing) {
      bouncing = true;
      // Re-check after a beat: the post page passes through "/" while it sets up its history.
      setTimeout(function () {
        bouncing = false;
        if (marked() && isHome() && !urnFrom(location.pathname, location.search)) { unmark(); location.replace('/notifications/'); }
      }, 350);
    }
    return true;
  }
  // Mark the Network and Notifications pages so the suggestion and news rules stay scoped to them.
  function markPath() {
    var seg = location.pathname.split('/')[1] || '';
    var root = document.documentElement;
    root.classList.toggle('feedoff-network', seg === 'mynetwork');
    root.classList.toggle('feedoff-notifications', seg === 'notifications');
  }
  function apply() {
    markPath();
    if (openPost() || backFromPost()) { document.documentElement.classList.add('feedoff-home'); return; }
    var home = on() && isHome();
    document.documentElement.classList.toggle('feedoff-home', home);
  }
  openPost();
  markPath();
  setTimeout(apply, 800);
  FO && FO.onSweep(apply);
  window.addEventListener('popstate', function () { setTimeout(apply, 50); });
})();

jsLibrary.noAutoplayNext:
// YouTube desktop: pause when a video ends and keep the Autoplay toggle off.
(function () {
  if (!/youtube\.com$/.test(location.hostname)) return;
  function killAutonav() {
    document.querySelectorAll('.ytp-autonav-toggle-button[aria-checked="true"]').forEach((b) => { try { b.click(); } catch (_) {} });
  }
  function hook(video) {
    if (video.__foHooked) return;
    video.__foHooked = true;
    video.addEventListener('ended', () => { try { video.pause(); } catch (_) {} killAutonav(); });
  }
  function sweep() { document.querySelectorAll('video').forEach(hook); killAutonav(); }
  window.__feedoff && window.__feedoff.onSweep(sweep);
  sweep();
})();

jsLibrary.xFollowingOnly:
// X: open Home on "Following", hide the "For you" tab, and mark the Explore page for CSS scoping.
(function () {
  if (!/(^|\.)x\.com$|twitter\.com$/.test(location.hostname)) return;
  var FO = window.__feedoff;
  function on() { return !FO || !FO.enabled || FO.enabled.indexOf('foryou') !== -1; }
  var last = 0;
  function tabs() {
    var all = document.querySelectorAll('[role="tab"]');
    var forYou = null, following = null;
    all.forEach(function (t) {
      var txt = (t.textContent || '').trim().toLowerCase();
      if (txt === 'for you') forYou = t; else if (txt === 'following') following = t;
    });
    // Other languages: the Home timeline's first two tabs are always For you, then Following.
    if (!forYou && !following) {
      // The tab row sits in the top bar on phones and in the main column on desktop.
      var lists = document.querySelectorAll('[role="tablist"]');
      for (var i = 0; i < lists.length; i++) {
        var own = lists[i].querySelectorAll('[role="tab"]');
        if (own.length >= 2) { forYou = own[0]; following = own[1]; break; }
      }
    }
    return { forYou: forYou, following: following };
  }
  function check() {
    document.documentElement.classList.toggle('feedoff-explore', /^\/explore/.test(location.pathname));
    if (!on() || !/^\/home\/?$/.test(location.pathname)) return;
    var t = tabs(); if (!t.forYou || !t.following) return;
    if (t.forYou.getAttribute('aria-selected') === 'true') {
      var now = Date.now(); if (now - last < 1500) return; last = now;
      try { t.following.click(); } catch (e) {}
    }
    t.forYou.style.setProperty('display', 'none', 'important');
  }
  setTimeout(check, 1200);
  FO && FO.onSweep(check);
  window.addEventListener('popstate', function () { setTimeout(check, 100); });
})();

jsLibrary.ytAdSkip:
// YouTube: if an ad still plays, mute it and jump to its end; click Skip/close when offered.
(function () {
  if (!/youtube\.com$/.test(location.hostname)) return;
  var FO = window.__feedoff;
  function on() { return !FO || !FO.enabled || FO.enabled.indexOf('ads') !== -1; }
  var wasMuted = null;
  function tick() {
    if (!on()) return;
    var ad = document.querySelector('.ad-showing, .ad-interrupting, .ytp-ad-player-overlay, ytm-player-ad-overlay, .ytp-ad-preview-container');
    var v = document.querySelector('video');
    if (ad && v) {
      if (wasMuted === null) wasMuted = v.muted;
      v.muted = true;
      if (isFinite(v.duration) && v.duration > 0) { try { v.currentTime = v.duration; } catch (e) {} }
      try { v.playbackRate = 16; } catch (e) {}
    } else if (v && wasMuted !== null) {
      v.muted = wasMuted; wasMuted = null;
      try { if (v.playbackRate === 16) v.playbackRate = 1; } catch (e) {}
    }
    var skip = document.querySelector('.ytp-ad-skip-button, .ytp-ad-skip-button-modern, .ytp-skip-ad-button, button.ytm-skip-ad-button, [class*="skip-button"], [id*="skip-button"]');
    if (skip) { try { skip.click(); } catch (e) {} }
    var close = document.querySelector('.ytp-ad-overlay-close-button, .ytm-ad-overlay-close');
    if (close) { try { close.click(); } catch (e) {} }
  }
  setInterval(tick, 400);
  FO && FO.onSweep(tick);
})();

jsLibrary.homeNoteDesktop:
// Desktop Reddit / Facebook: mark the home page so the CSS can empty its feed, and leave a short
// note where the feed was. The note is drawn by the engine's own placeholder style, so nothing is
// inserted into the page (these sites re-render their trees and trip over foreign nodes).
(function () {
  var FO = window.__feedoff;
  var host = location.hostname.replace(/^www\./, '');
  var SITES = {
    'reddit.com': { home: /^\/(r\/(popular|all)\/?|best\/?)?$/, anchor: 'shreddit-feed', note: 'Home feed hidden by FeedOff.\nPick a community from the sidebar, or search for one.' },
    'facebook.com': { home: /^\/(home\.php)?$/, anchor: "[role='main'] div:has(> h3:first-child + div)", note: 'News Feed hidden by FeedOff.\nGroups, Marketplace, messages and events work as usual.' }
  };
  var site = SITES[host];
  if (!site) return;
  var ATTRS = ['data-feedoff-homenote', 'data-feedoff-after', 'data-feedoff-hidden', 'data-feedoff-note'];
  function on() { return !FO || !FO.enabled || FO.enabled.indexOf('homefeed') !== -1; }
  function clear(el) { ATTRS.forEach(function (a) { el.removeAttribute(a); }); }
  function apply() {
    var home = on() && site.home.test(location.pathname);
    document.documentElement.classList.toggle('feedoff-home', home);
    var marked = document.querySelectorAll('[data-feedoff-homenote]');
    if (!home) { marked.forEach(clear); return; }
    var el = null; try { el = document.querySelector(site.anchor); } catch (e) {}
    marked.forEach(function (m) { if (m !== el) clear(m); });
    if (el && (el.getAttribute('data-feedoff-hidden') !== 'end' || !el.hasAttribute('data-feedoff-homenote'))) {
      el.setAttribute('data-feedoff-homenote', '1');
      el.setAttribute('data-feedoff-after', '1');
      el.setAttribute('data-feedoff-hidden', 'end');
      el.setAttribute('data-feedoff-note', site.note);
    }
  }
  apply();
  setTimeout(apply, 800);
  FO && FO.onSweep(apply);
  window.addEventListener('popstate', function () { setTimeout(apply, 50); });
})();

